CREATE TABLE IF NOT EXISTS folder_scan_runs (sourceId TEXT NOT NULL, generation INTEGER NOT NULL, state TEXT NOT NULL, discoveryAtEpochMs INTEGER NOT NULL, PRIMARY KEY(sourceId));
CREATE TABLE IF NOT EXISTS folder_scan_directories (sourceId TEXT NOT NULL, documentHash TEXT NOT NULL, encryptedDocumentId TEXT NOT NULL, generation INTEGER NOT NULL, depth INTEGER NOT NULL, state TEXT NOT NULL, error TEXT, lastVisitedAtEpochMs INTEGER NOT NULL, PRIMARY KEY(sourceId,documentHash));
CREATE INDEX IF NOT EXISTS index_folder_scan_directories_sourceId_generation_state_depth ON folder_scan_directories(sourceId,generation,state,depth);
CREATE TABLE IF NOT EXISTS folder_scan_items (sourceId TEXT NOT NULL, documentHash TEXT NOT NULL, generation INTEGER NOT NULL, encryptedEntry TEXT NOT NULL, providerSize INTEGER, providerModifiedAtEpochMs INTEGER, observedAtEpochMs INTEGER NOT NULL, state TEXT NOT NULL, scopeResult TEXT NOT NULL, ruleVersion INTEGER NOT NULL, error TEXT, attempts INTEGER NOT NULL, PRIMARY KEY(sourceId,documentHash));
CREATE INDEX IF NOT EXISTS index_folder_scan_items_sourceId_generation_state_providerModifiedAtEpochMs ON folder_scan_items(sourceId,generation,state,providerModifiedAtEpochMs);
